{"content": "`timescale 1ns/1ps
// Exercise the two real AHB stages between AE350 EXTS and the Neo GPU.
// The hard AE350 macro is replaced by a protocol-correct, stalled master.
module bench;
    reg hclk=0,mem_clk=0,resetn=0;
    always #6.25 hclk=~hclk;
    initial begin #0.371;forever #6.667 mem_clk=~mem_clk;end
    reg hsel=0,hwrite=0;
    reg [31:0] haddr=0,hwdata=0;
    reg [1:0] htrans=0;
    wire hready;wire [31:0] hrdata;
    wire [1:0] leg_sel,leg_trans;
    wire leg_write,leg_ready;wire [31:0] leg_addr,leg_wdata,leg_rdata;
    ahb_exts_bridge bridge(.hclk(hclk),.hresetn(resetn),
        .m_hsel(hsel),.m_haddr(haddr),.m_htrans(htrans),.m_hwrite(hwrite),.m_hwdata(hwdata),
        .m_hrdata(hrdata),.m_hready(hready),
        .s_hsel(leg_sel),.s_htrans(leg_trans),.s_hwrite(leg_write),.s_haddr(leg_addr),.s_hwdata(leg_wdata),
        .s0_hrdata(32'hbad00000),.s0_hready(1'b1),.s1_hrdata(leg_rdata),.s1_hready(leg_ready));
    wire bus_sel,bus_write,bus_ready;wire [1:0] bus_trans;
    wire [31:0] bus_addr,bus_wdata,bus_rdata;
    video_bus_stage stage(.clk(hclk),.resetn(resetn),
        .s_hsel(leg_sel[1]),.s_hwrite(leg_write),.s_htrans(leg_trans),.s_haddr(leg_addr),.s_hwdata(leg_wdata),
        .s_hready(leg_ready),.s_hrdata(leg_rdata),
        .m_hsel(bus_sel),.m_hwrite(bus_write),.m_htrans(bus_trans),.m_haddr(bus_addr),.m_hwdata(bus_wdata),
        .m_hready(bus_ready),.m_hrdata(bus_rdata));
    reg [2:0] selected=0;
    always @(posedge hclk)
        if(!resetn)selected<=0;else if(bus_sel)selected<=bus_addr[14:12];
    wire [31:0] gpu_data,debug_data;
    wire gpu_ready,debug_ready,valid,write,debug_accept;
    wire [28:0] addr;
    wire [255:0] wr_data,debug_state;wire [31:0] wr_mask;
    assign bus_ready=selected==1 ? gpu_ready:selected==5 ? debug_ready:1'b1;
    assign bus_rdata=selected==1 ? gpu_data:selected==5 ? debug_data:32'hbad00001;
    gpu_accel #(.FONT_FILE("font8x16.hex")) gpu(
        .hclk(hclk),.hresetn(resetn),.mem_clk(mem_clk),
        .hsel(bus_sel && bus_addr[14:12]==1),.hwrite(bus_write),.haddr(bus_addr),.hwdata(bus_wdata),.htrans(bus_trans),
        .hrdata(gpu_data),.hready(gpu_ready),.valid(valid),.write(write),.addr(addr),.wr_data(wr_data),.wr_mask(wr_mask),
        .ready(native_ready),.rd_data(256'd0),.rd_valid(1'b0),.debug_state(debug_state),.debug_accept(debug_accept));
    wire native_ready;
    neo_gpu_debug debug_port(.hclk(hclk),.resetn(resetn),.mem_clk(mem_clk),
        .hsel(bus_sel && bus_addr[14:12]==5),.hwrite(bus_write),.htrans(bus_trans),.haddr(bus_addr),.hwdata(bus_wdata),
        .hrdata(debug_data),.hready(debug_ready),.host_accept(debug_accept),.live(debug_state));

    integer tick=0,accepted=0,stalls=0;
    wire men,mwen,mwend;wire[2:0]mcmd;wire[28:0]maddr;
    wire[255:0]mdata;wire[31:0]mmask;
    wire mrdy=(tick%7!=0 && tick%7!=1),mwrdy=(tick%5!=0);
    ddr_gpu_arb arb(.clk(mem_clk),.rst_n(resetn),
      .c_en(1'b0),.c_cmd(3'd0),.c_addr(29'd0),.c_ready(),
      .c_wr_en(1'b0),.c_wr_end(1'b0),.c_wr_data(256'd0),.c_wr_mask(32'hffffffff),
      .c_wr_ready(),.c_rd_data(),.c_rd_valid(),.c_rd_end(),
      .g_valid(1'b0),.g_addr(29'd0),.g_ready(),.g_data(),.g_data_valid(),
      .b_valid(valid),.b_write(write),.b_addr(addr),.b_wr_data(wr_data),.b_wr_mask(wr_mask),
      .b_ready(native_ready),.b_rd_data(),.b_rd_valid(),.m_en(men),.m_cmd(mcmd),.m_addr(maddr),
      .m_ready(mrdy),.m_wr_en(mwen),.m_wr_end(mwend),.m_wr_data(mdata),.m_wr_mask(mmask),
      .m_wr_ready(mwrdy),.m_rd_data(256'd0),.m_rd_valid(1'b0),.m_rd_end(1'b0));
    always @(posedge mem_clk)begin
      tick<=tick+1;
      if(resetn && valid && !native_ready)stalls<=stalls+1;
      if(resetn && men && mrdy)begin
        if(mcmd!=0 || !mwen || !mwrdy || !mwend || maddr!==29'h04800008 ||
           mmask!==0 || mdata!=={16{16'h6b4d}})$fatal(1,"CHECK_FAIL FOOTPRINT");
        accepted<=accepted+1;
      end
    end
    task access(input bit wr,input [31:0] address,input [31:0] data,output [31:0] result);
        @(negedge hclk);while(!hready)@(negedge hclk);
        hsel=1;htrans=2;hwrite=wr;haddr=address;
        @(negedge hclk);hsel=0;htrans=0;hwdata=data;
        do @(negedge hclk);while(!hready);
        result=hrdata;hwdata=0;hwrite=0;
    endtask

    reg[31:0]value,words[0:15];integer received=0;
    always @(posedge mem_clk)if(resetn && gpu.command_we)begin
      if(received>=16 || gpu.queue_data!==words[received])$fatal(1,"CHECK_FAIL PAYLOAD");
      received=received+1;
    end
    task wait_done(input[31:0]wanted);
      integer polls;begin
       polls=0;value=0;
       while(value!=wanted && polls<400)begin
        access(0,32'he9001008,0,value);polls=polls+1;
       end
       if(value!=wanted)$fatal(1,"CHECK_FAIL COMPLETION done=%0d want=%0d",value,wanted);
      end
    endtask
    initial begin
      words[0]='h16000000;words[1]='h12000020;words[2]='h12000040;
      words[3]='h00100001;words[4]='h00200020;words[5]=0;words[6]=0;words[7]=0;
      words[8]='h1c000000;words[9]=1;words[10]='h6b4d;words[11]=0;
      words[12]=0;words[13]='h00100001;words[14]=0;words[15]=0;
      repeat(8)@(negedge hclk);resetn=1;repeat(20)@(negedge hclk);
      access(0,'he9001000,0,value);if(value!=='h424c5432)$fatal(1,"CHECK_FAIL ID");
      for(integer i=0;i<8;i++)access(1,'he9001010,words[i],value);
      wait_done(1);if(accepted!=0)$fatal(1,"CHECK_FAIL TARGET_DMA");
      for(integer i=8;i<16;i++)access(1,'he9001010,words[i],value);
      wait_done(2);repeat(40)@(negedge hclk);
      access(0,'he9001004,0,value);if(value!=0)$fatal(1,"CHECK_FAIL BUSY");
      access(0,'he9001034,0,value);if(value!=0)$fatal(1,"CHECK_FAIL REJECT");
      if(accepted!=1 || received!=16 || stalls==0)$fatal(1,"CHECK_FAIL COVERAGE");
      $display("BASELINE_PASS accepted=%0d words=%0d stalls=%0d",accepted,received,stalls);
      $finish;
    end
    initial begin #1000000;$fatal(1,"CHECK_FAIL WATCHDOG");end
endmodule
"}

{"content": "// ahb_exts_bridge.v — pont registré entre l'interface AHB étendue (EXTS) du SoC AE350 et ses deux esclaves de fabric : ext_regs (0)
// et la carte vidéo ahb_video (1, haddr[24] = 1). Pourquoi : l'entrée EXTS_HREADYIN du bloc dur consomme ≈ 9 ns de budget à elle seule
// (builds V5_p11 : un registre → HREADYIN à −0,03 ns ; p12-p14 : un mux devant HREADYIN à −5 / −8 ns). Ici le SoC ne voit que des
// registres : m_hready et m_hrdata sont des bascules, sans logique devant. Un accès prend 4 cycles (5 pour une lecture d'ext_regs) :
// I (adresse acceptée) → DATA (hwdata capturé, adresse relayée à l'esclave) → ADDR (esclave en phase de données) → WAIT (sa réponse)
// → I. Un seul accès en vol (le SoC est retenu). Les esclaves gardent leur protocole AHB-lite d'origine, inchangés.
`default_nettype none
module ahb_exts_bridge (
    input  wire        hclk,
    input  wire        hresetn,
    // côté SoC (EXTS)
    input  wire        m_hsel,
    input  wire [31:0] m_haddr,
    input  wire [1:0]  m_htrans,
    input  wire        m_hwrite,
    input  wire [31:0] m_hwdata,
    output reg  [31:0] m_hrdata,
    output reg         m_hready,
    // côté esclaves (0 = ext_regs, 1 = vidéo) : adresse/données partagées, sélection séparée
    output reg  [1:0]  s_hsel,
    output reg  [1:0]  s_htrans,
    output reg         s_hwrite,
    output reg  [31:0] s_haddr,
    output reg  [31:0] s_hwdata,
    input  wire [31:0] s0_hrdata,
    input  wire        s0_hready,
    input  wire [31:0] s1_hrdata,
    input  wire        s1_hready
);
    localparam I = 0, DATA = 1, ADDR = 2, WAIT = 3;
    reg [3:0] st; reg wr, tgt; reg [31:0] addr;
    wire        t_hready = tgt ? s1_hready : s0_hready;
    wire [31:0] t_hrdata = tgt ? s1_hrdata : s0_hrdata;
    always @(posedge hclk) begin
        if (!hresetn) begin st <= 4'b0001; wr <= 1'b0; tgt <= 1'b0; addr <= 32'd0; s_hsel <= 2'b00; s_htrans <= 2'b00; s_hwrite <= 1'b0; s_haddr <= 32'd0; s_hwdata <= 32'd0; m_hrdata <= 32'd0; m_hready <= 1'b1; end
        else begin
            s_hsel <= 2'b00; s_htrans <= 2'b00;
            // All reachable IDLE cycles have HREADY=1. Assign its complete
            // next value every cycle: avoid a second, long slave-ready
            // decode through the clock enable of the hard-core return FF.
            m_hready <= (st[I] && !(m_hsel && m_htrans[1])) || (st[WAIT] && t_hready);
            // One-hot transitions keep the hard macro's HREADY -> HSEL
            // round trip off a binary next-state decoder.
            st[I] <= (st[I] && !(m_hsel && m_htrans[1])) || (st[WAIT] && t_hready);
            st[DATA] <= st[I] && m_hsel && m_htrans[1];
            st[ADDR] <= st[DATA];
            st[WAIT] <= st[ADDR] || (st[WAIT] && !t_hready);
            case (1'b1)
                st[I]: begin
                    // Sample private payload while idle. Only acceptance
                    // advances to DATA; unselected samples are never issued.
                    // Keep the hard-core HREADYIN -> HSEL path off the
                    // 34 payload register enables without adding latency.
                    wr <= m_hwrite; addr <= m_haddr; tgt <= m_haddr[24];
                    // HREADY is always high in reachable IDLE, including
                    // immediately after reset or completion of WAIT.
                end
                st[DATA]: begin s_hwdata <= m_hwdata; s_hsel <= tgt ? 2'b10 : 2'b01; s_htrans <= 2'b10; s_hwrite <= wr; s_haddr <= addr; end
                // The SoC only consumes HRDATA when registered HREADY rises.
                // Sampling during stalls removes ready from 32 data enables.
                st[WAIT]: m_hrdata <= t_hrdata;
                default: ;
            endcase
        end
    end
endmodule
`default_nettype wire
"}

{"content": "// Serialize the video peripheral leg of the AE350 AHB bus.
// Register both directions, removing combinational slave-HREADY -> HSEL
// chains between distant graphics and USB register blocks. Backend transfers
// have one address pulse, a stable data phase, and an idle gap. No clock CDC.
`default_nettype none
module video_bus_stage(
 input wire clk,resetn,
 input wire s_hsel,s_hwrite,input wire [1:0] s_htrans,
 input wire [31:0] s_haddr,s_hwdata,
 output wire s_hready,output reg [31:0] s_hrdata,
 output wire m_hsel,output reg m_hwrite,output wire [1:0] m_htrans,
 output reg [31:0] m_haddr,m_hwdata,
 input wire m_hready,input wire [31:0] m_hrdata
);
 localparam IDLE=0,CAPTURE=1,WAIT_IDLE=2,ADDRESS=3,DATA=4,RESPONSE=5;
 reg [2:0] state;
 assign s_hready=state==IDLE||state==RESPONSE;
 assign m_hsel=state==ADDRESS;
 assign m_htrans=state==ADDRESS ? 2'b10:2'b00;
 always @(posedge clk)begin
  if(!resetn)begin state<=IDLE;s_hrdata<=0;m_hwrite<=0;m_haddr<=0;m_hwdata<=0;end
  else case(state)
   IDLE,RESPONSE:begin
    if(s_hsel&&s_htrans[1])begin m_haddr<=s_haddr;m_hwrite<=s_hwrite;state<=CAPTURE;end
    else state<=IDLE;
   end
   CAPTURE:begin m_hwdata<=s_hwdata;state<=WAIT_IDLE;end
   WAIT_IDLE:if(m_hready)state<=ADDRESS;
   ADDRESS:state<=DATA;
   // Data may be sampled during a wait; only RESPONSE makes it visible to
   // the master. This removes distant HREADY from all 32 data enables.
   DATA:begin s_hrdata<=m_hrdata;if(m_hready)state<=RESPONSE;end
   default:state<=IDLE;
  endcase
 end
endmodule
`default_nettype wire
"}

{"content": "// Shared native DDR3 UI: CPU adapter, scanout reads and blitter reads/writes.
// Addresses are 32-bit words, aligned to eight words (32 bytes).
// CPU upstream issues command+data pulses only when ready; capture them in a
// one-entry buffer to break the ready chain through the legacy CPU adapter.
// Scanout has priority for bounded line fetches; CPU/blitter alternate otherwise.
// Their grant is registered, so changing clients may insert an idle cycle.
`default_nettype none
module ddr_gpu_arb (
    input wire clk, rst_n,
    input wire c_en,
    input wire [2:0] c_cmd,
    input wire [28:0] c_addr,
    output wire c_ready,
    input wire c_wr_en, c_wr_end,
    input wire [255:0] c_wr_data,
    input wire [31:0] c_wr_mask,
    output wire c_wr_ready,
    output wire [255:0] c_rd_data,
    output wire c_rd_valid, c_rd_end,
    input wire g_valid,
    input wire [28:0] g_addr,
    output wire g_ready,
    output wire [255:0] g_data,
    output wire g_data_valid,
    input wire b_valid, b_write,
    input wire [28:0] b_addr,
    input wire [255:0] b_wr_data,
    input wire [31:0] b_wr_mask,
    output wire b_ready,
    output wire [255:0] b_rd_data,
    output wire b_rd_valid,
    output wire m_en,
    output wire [2:0] m_cmd,
    output wire [28:0] m_addr,
    input wire m_ready,
    output wire m_wr_en, m_wr_end,
    output wire [255:0] m_wr_data,
    output wire [31:0] m_wr_mask,
    input wire m_wr_ready,
    input wire [255:0] m_rd_data,
    input wire m_rd_valid, m_rd_end
);
    reg [1:0] tags [0:15]; // 0 CPU, 1 scanout, 2 blitter
    reg [4:0] wp = 0, rp = 0;
    reg full = 0;
    wire empty = wp == rp;
    wire issue = rst_n && !full;
    reg cpu_pending = 0;
    reg [2:0] cpu_cmd;
    reg [28:0] cpu_addr;
    reg [255:0] cpu_data;
    reg [31:0] cpu_mask;
    reg prefer_blitter = 1;
    reg take_blitter = 0;
    // Two scanout request slots isolate its distant owner/request decode
    // from DDR arbitration. READY acknowledges enqueueing; responses still
    // follow DDR issue order. The FIFO sustains one request per cycle when
    // DDR accepts continuously, and never depends on DDR READY at its input.
    reg [28:0] scan_addresses [0:1];
    reg scan_wp=0,scan_rp=0;
    reg [1:0] scan_count=0;
    wire scan_valid=scan_count!=0;
    wire [28:0] scan_addr=scan_addresses[scan_rp];
    assign g_ready = rst_n && scan_count!=2;
    wire scan_enqueue=g_valid && g_ready;
    wire scan_issue=scan_valid && issue && m_ready;
    always @(posedge clk)begin
        if(!rst_n)begin scan_wp<=0;scan_rp<=0;scan_count<=0;end
        else begin
            if(scan_enqueue)begin scan_addresses[scan_wp]<=g_addr;scan_wp<=!scan_wp;end
            if(scan_issue)scan_rp<=!scan_rp;
            case({scan_enqueue,scan_issue})
                2'b10:scan_count<=scan_count+1'b1;
                2'b01:scan_count<=scan_count-1'b1;
                default:;
            endcase
        end
    end
    // b_grant est gardé tel quel par la synthèse (syn_keep) : sans cela, la LUT de b_ready était partagée
    // avec m_wr_en, qui dépend de b_valid, et l'analyse de timing comptait une boucle combinatoire
    // b_valid -> arbitre -> b_ready -> blitter/V1 qui n'existe pas logiquement (r600, -0,47 ns).
    wire b_grant /* synthesis syn_keep=1 */ = issue && !scan_valid && take_blitter && m_ready && (!b_write || m_wr_ready);
    assign b_ready = b_grant;
    assign c_ready = rst_n && !cpu_pending;
    assign c_wr_ready = c_ready;
    wire cpu_fire = issue && !scan_valid && !take_blitter && cpu_pending && m_ready && (cpu_cmd != 0 || m_wr_ready);
    assign m_en = scan_issue || (b_valid && b_ready) || cpu_fire;
    assign m_cmd = scan_valid ? 3'b001 : take_blitter ? {2'b0,!b_write} : cpu_cmd;
    assign m_addr = scan_valid ? scan_addr : take_blitter ? b_addr : cpu_addr;
    assign m_wr_en = (b_valid && b_ready && b_write) || (cpu_fire && cpu_cmd == 0);
    assign m_wr_end = m_wr_en;
    assign m_wr_data = take_blitter ? b_wr_data : cpu_data;
    assign m_wr_mask = take_blitter ? b_wr_mask : cpu_mask;
    wire push = scan_issue || (b_valid && b_ready && !b_write) || (cpu_fire && cpu_cmd == 1);
    wire pop = m_rd_valid && !empty;
    wire [4:0] next_wp = wp + {4'b0, push};
    wire [4:0] next_rp = rp + {4'b0, pop};
    wire [4:0] incremented_wp = wp + 5'd1;
    wire one_slot_left = incremented_wp == {~rp[4],rp[3:0]};
    always @(posedge clk) begin
        if (!rst_n) begin
            wp <= 0; rp <= 0; full <= 0; prefer_blitter <= 1;
            take_blitter<=0;
            cpu_pending <= 0; cpu_cmd <= 0; cpu_addr <= 0; cpu_data <= 0; cpu_mask <= 32'hffffffff;
        end
        else begin
            // Cut the valid -> arbitration -> ready round trip. A stale grant
            // can only insert a bubble: native commands still require valid.
            // Acknowledgement remains the actual DDR command/data acceptance.
            if(b_valid && b_ready) take_blitter<=0;
            else take_blitter<=b_valid && (prefer_blitter || !cpu_pending);
            // While empty, sample the payload independently of the late
            // upstream request. The acceptance cycle captures the same words;
            // once pending, every word remains held until DDR accepts it.
            // This leaves c_en driving only the valid bit, not 320 payload CEs.
            if (!cpu_pending) begin
                cpu_cmd <= c_cmd; cpu_addr <= c_addr;
                cpu_data <= c_wr_data; cpu_mask <= c_wr_mask;
            end
            if (c_en && c_ready) cpu_pending <= 1;
            else if (cpu_fire) cpu_pending <= 0;
            if (!scan_valid) begin
                if (b_valid && b_ready) prefer_blitter <= 0;
                else if (cpu_fire) prefer_blitter <= 1;
            end
            if (push) tags[wp[3:0]] <= scan_valid ? 2'd1 : take_blitter ? 2'd2 : 2'd0;
            wp <= next_wp; rp <= next_rp;
            // Compare stable pointers before the late command acceptance.
            // Simultaneous push/pop leaves occupancy unchanged.
            if(push && !pop)full<=one_slot_left;
            else if(pop && !push)full<=0;
        end
    end
    assign c_rd_data = m_rd_data;
    assign g_data = m_rd_data;
    assign c_rd_valid = pop && tags[rp[3:0]] == 0;
    assign c_rd_end = c_rd_valid && m_rd_end;
    assign g_data_valid = pop && tags[rp[3:0]] == 1;
    assign b_rd_data = m_rd_data;
    assign b_rd_valid = pop && tags[rp[3:0]] == 2;
endmodule
`default_nettype wire
"}

{"content": "// G2 AHB command queue + rasterizer + native DDR3 DMA, at 0xE9001000.
// A command contains eight words. Completion counter is the software fence;
// BUSY is a synchronized status indication, not a substitute for that fence.
`default_nettype none
module gpu_accel #(
    parameter FONT_FILE = "rtl/video/font8x16.hex"
) (
    input wire hclk, hresetn, hsel, hwrite,
    input wire [31:0] haddr, hwdata,
    input wire [1:0] htrans,
    output reg [31:0] hrdata,
    output wire hready,
    input wire mem_clk,
    output wire valid, write,
    output wire [28:0] addr,
    output wire [255:0] wr_data,
    output wire [31:0] wr_mask,
    input wire ready,
    input wire [255:0] rd_data,
    input wire rd_valid,
    output wire [255:0] debug_state,
    output wire debug_accept,
    output wire [63:0] observe_packet_words
);
    reg [1:0] mrst /* synthesis syn_preserve=1 */ = 0;   // voir gpu_scanout.v
    always @(posedge mem_clk or negedge hresetn)
        if (!hresetn) mrst <= 0; else mrst <= {mrst[0], 1'b1};
    // Copies du dernier étage, avec exactement les mêmes cycles que mrst[1].
    // Le registre unique alimentait 11 871 charges dans c2, dont les resets
    // DSP du raster à l'autre bout du circuit. Garder une sortie par moteur.
    // Le DMA possède aussi sa copie : partager celle du blitter créait
    // un aller-retour reset -> DMA -> adresses BSRAM du blitter (C19).
    reg [11:0] engine_resetn /* synthesis syn_preserve=1 */ = 0;
    always @(posedge mem_clk or negedge hresetn)
        if (!hresetn) engine_resetn <= 0;
        else engine_resetn <= {12{mrst[0]}};
    reg [7:0] bus_addr;
    reg bus_write,bus_command,read_wait;
    wire queue_full;
    // Register command-port decode during the AHB address phase, keeping
    // the address comparator off the CPU's HREADY feedback path.
    // AHB master and this FIFO share reset. Use registered fullness here:
    // the generic FIFO's reset-gated READY must not enter CPU feedback.
    assign hready = !(bus_command && queue_full) && !read_wait;
    // Capture CSR data locally before crossing the chip to the peripheral
    // bridge. Each read inserts one AHB wait state; writes are unchanged.
    always @(posedge hclk)begin
        if(!hresetn)read_wait<=0;
        else if(read_wait)read_wait<=0;
        else if(hready)read_wait<=hsel && htrans[1] && !hwrite;
    end
    // Used only at font addresses 14/18, which cannot be a FIFO command.
    // Queue fullness therefore cannot stall these writes. Keeping FULL out
    // of this enable avoids a long path across the AHB/font regions.
    wire write_fire = bus_write && !read_wait && hresetn;
    reg [11:0] font_write_addr;
    always @(posedge hclk) begin
        if (!hresetn) begin bus_addr <= 0; bus_write <= 0; bus_command<=0; font_write_addr <= 0; end
        else begin
            if (hready) begin
                bus_addr <= haddr[7:0]; bus_write <= hsel && htrans[1] && hwrite;
                bus_command<=hsel && htrans[1] && hwrite && haddr[7:0]==8'h10;
            end
            if (write_fire && bus_addr == 8'h14) font_write_addr <= hwdata[11:0];
            if (write_fire && bus_addr == 8'h18) font_write_addr <= font_write_addr + 1'b1;
        end
    end
    wire queue_valid, queue_pop;
    wire [31:0] queue_data, queue_lost;
    wire [7:0] queue_count, queue_rd_count;
    ddr_dcfifo #(.WIDTH(32), .DEPTH_LOG2(7)) u_commands (
        .wr_clk(hclk), .wr_rst(!hresetn), .wr_valid(bus_command && !queue_full),
        .wr_data(hwdata), .wr_ready(), .wr_full(queue_full), .wr_lost(queue_lost), .wr_count(queue_count),
        .rd_clk(mem_clk), .rd_rst(!mrst[1]), .rd_valid(queue_valid), .rd_data(queue_data),
        .rd_ready(queue_pop), .rd_count(queue_rd_count));
    wire command_full, blitter_busy;
    reg [2:0] command_word;
    // Reserve a whole command in the rasterizer FIFO, then send all eight words.
    assign queue_pop = mrst[1] && (command_word != 0 || !command_full);
    wire command_we = queue_valid && queue_pop;
    always @(posedge mem_clk) begin
        if (!mrst[1]) command_word <= 0;
        else if (command_we) command_word <= command_word + 1'b1;
    end
    wire [15:0] done_count, command_lost, command_bad, r_done;
    wire [31:0] r_errors;
    wire [31:0] raster_rejected,raster_fragments,raster_passed;
    wire [31:0] r_rejected,r_fragments,r_passed;
    wire [31:0] v1_rejected,v1_fragments,v1_passed,v1_hits,v1_misses;
    wire [31:0] v1r_rejected,v1r_fragments,v1r_passed,v1r_hits,v1r_misses;
    cdc_word u_v1_bad(.src_clk(mem_clk),.src_data(v1_rejected),.dst_clk(hclk),.dst_data(v1r_rejected));
    cdc_word u_v1_frag(.src_clk(mem_clk),.src_data(v1_fragments),.dst_clk(hclk),.dst_data(v1r_fragments));
    cdc_word u_v1_pass(.src_clk(mem_clk),.src_data(v1_passed),.dst_clk(hclk),.dst_data(v1r_passed));
    cdc_word u_v1_hits(.src_clk(mem_clk),.src_data(v1_hits),.dst_clk(hclk),.dst_data(v1r_hits));
    cdc_word u_v1_miss(.src_clk(mem_clk),.src_data(v1_misses),.dst_clk(hclk),.dst_data(v1r_misses));
    cdc_word u_raster_rejected (.src_clk(mem_clk),.src_data(raster_rejected),.dst_clk(hclk),.dst_data(r_rejected));
    cdc_word u_raster_fragments (.src_clk(mem_clk),.src_data(raster_fragments),.dst_clk(hclk),.dst_data(r_fragments));
    cdc_word u_raster_passed (.src_clk(mem_clk),.src_data(raster_passed),.dst_clk(hclk),.dst_data(r_passed));
    cdc_word #(.WIDTH(16)) u_done (.src_clk(mem_clk), .src_data(done_count), .dst_clk(hclk), .dst_data(r_done));
    cdc_word u_errors (.src_clk(mem_clk), .src_data({command_bad,command_lost}), .dst_clk(hclk), .dst_data(r_errors));
    reg [1:0] busy_sync;
    always @(posedge hclk) begin
        if (!hresetn) busy_sync <= 0;
        else busy_sync <= {busy_sync[0], blitter_busy || queue_valid || command_word != 0};
    end
    // Decode in the AHB address phase, then register the selected response.
    // Une copie par octet de réponse : le sélecteur ne doit pas piloter
    // les 32 bits dispersés du mux de statistiques. Les quatre copies
    // capturent la même adresse sur le même front, sans cycle ajouté.
    reg [103:0] read_select /* synthesis syn_preserve=1 */;
    genvar reg_index;
    generate for(reg_index=0;reg_index<104;reg_index=reg_index+1)begin: read_decode
        always @(posedge hclk)
            if(!hresetn)read_select[reg_index]<=(reg_index%26==0);
            // Only reads need this selector held through their data wait.
            // A stalled FIFO write has no CSR response to preserve.
            else if(!read_wait)read_select[reg_index]<=(haddr[7:0]==(reg_index%26)*4);
    end endgenerate
    // Comme HREADY, le statut utilise FULL enregistré. Le maître partage
    // HRESETn : toute lecture valide voit FULL == !READY, sans propager
    // le réseau de reset dans le retour de données du pont CPU.
    wire [31:0] register_value [0:25];
    assign register_value[0]=32'h424c5432;
    assign register_value[1]={30'b0,queue_full,busy_sync[1]};
    assign register_value[2]={16'b0,r_done};
    assign register_value[3]=r_errors;
    assign register_value[4]=32'd0;
    assign register_value[5]={20'b0,font_write_addr};
    assign register_value[6]=32'd0;
    assign register_value[7]=queue_lost;
    assign register_value[8]=32'h0000001f;
    assign register_value[9]=r_rejected;
    assign register_value[10]=r_fragments;
    assign register_value[11]=r_passed;
    assign register_value[12]=32'h000001ff;
    assign register_value[13]=v1r_rejected;
    assign register_value[14]=v1r_fragments;
    assign register_value[15]=v1r_passed;
    assign register_value[16]=v1r_hits;
    assign register_value[17]=v1r_misses;
    wire [31:0] geometry_stat [0:6];
    wire [31:0] geometry_read [0:6];
    genvar geometry_index;
    generate for(geometry_index=0;geometry_index<7;geometry_index=geometry_index+1)begin: geometry_cdc
        cdc_word u_stat(.src_clk(mem_clk),.src_data(geometry_stat[geometry_index]),.dst_clk(hclk),.dst_data(geometry_read[geometry_index]));
        assign register_value[19+geometry_index]=geometry_read[geometry_index];
    end endgenerate
    assign register_value[18]=32'h47334431; // G3D1 geometry ABI; legacy V1 capability remains unchanged.
    reg [31:0] response_data;
    always @(posedge hclk)
        if(!hresetn)hrdata<=0;
        else hrdata<=response_data;
    genvar response_byte;
    generate for(response_byte=0;response_byte<4;response_byte=response_byte+1)begin: read_response
        integer k;
        always @* begin
            response_data[response_byte*8+:8]=8'd0;
            for(k=0;k<26;k=k+1)
                response_data[response_byte*8+:8]=response_data[response_byte*8+:8] |
                    ({8{read_select[response_byte*26+k]}} & register_value[k][response_byte*8+:8]);
        end
    end endgenerate
    wire [95:0] debug_blitter;
    wire [11:0] font_addr;
    wire [7:0] font_q;
    font_ram #(.FONT_FILE(FONT_FILE)) u_font (
        .wclk(hclk), .rclk(mem_clk), .we(write_fire && bus_addr == 8'h18),
        .waddr(font_write_addr), .wdata(hwdata[7:0]), .raddr(font_addr), .q(font_q));
    wire f_req,f_done;
    wire [24:0] f_addr;
    wire [10:0] f_len;
    wire [7:0] f_color;
    wire s_req, s_valid, s_done, w_req, w_ready, w_done, c_req, c_ack;
    wire [23:0] s_addr, w_addr, c_addr;
    wire [9:0] s_len, w_len;
    wire [15:0] s_data, w_data, c_data;
    wire [1:0] w_mask, c_mask;
    wire ext_start,ext_active,ext_done;
    wire [255:0] ext_command;
    wire legacy_valid,legacy_write,raster_valid,raster_write;
    wire [28:0] legacy_addr,raster_addr;
    wire [255:0] legacy_data,raster_data;
    wire [31:0] legacy_mask,raster_mask;
    // The opcode is stable before ext_start; latch ownership outside a command.
    // This keeps opcode decode off the arbiter READY feedback path.
    reg v1_select;
    // Keep raster control separate from the wide payload mux. N29 routed
    // v1_select to 487 loads and across the device before raster CE decode.
    // This is the complementary value at the same cycle, not another stage.
    reg raster_selected /* synthesis syn_preserve=1 */;
    always @(posedge mem_clk)begin
        if(!mrst[1])begin v1_select<=0;raster_selected<=1;end
        else if(!ext_active)begin
            v1_select<=ext_command[31:24]>=22;
            raster_selected<=ext_command[31:24]<22;
        end
    end
    wire old_done,v1_done,v1_valid,v1_write,v1_request;
    reg v1_accepted,v1_pending,v1_tx_write,v1_rx_valid;
    reg [28:0] v1_tx_addr;
    reg [255:0] v1_tx_data;
    // (syn_preserve : voir gpu_raster.v, copie locale du bus de lecture DDR)
    reg [255:0] v1_rx_data /* synthesis syn_preserve=1 */;
    reg [31:0] v1_tx_mask;
    wire [28:0] v1_addr;
    wire [255:0] v1_data;
    wire [31:0] v1_mask;
    // Both extended raster engines share one registered DDR transaction stage.
    // This also cuts scanout arbitration -> legacy raster next-state paths.
    wire extended_request=v1_select ? v1_request:raster_valid;
    // Isolate the extended shaders' request multiplexers and wide reply loads
    // from the shared DDR arbiter. Hold one complete transaction until accepted.
    // The acknowledgement guard prevents recapturing the engine's old VALID
    // on the cycle in which it observes the registered acceptance pulse.
    always @(posedge mem_clk)begin
        v1_rx_data<=rd_data;
        if(!mrst[1])begin
            v1_accepted<=0;v1_pending<=0;v1_rx_valid<=0;
        end else begin
            v1_accepted<=v1_pending && ready;
            v1_rx_valid<=rd_valid && ext_active;
            if(v1_pending)begin
                if(ready)v1_pending<=0;
            end else if(extended_request && !v1_accepted)begin
                v1_pending<=1;
            end
        end
    end
    // Prefetch only while the transaction slot is empty. REQUEST drives
    // PENDING alone; held payload and accepted DDR cycles remain unchanged.
    always @(posedge mem_clk)begin
        if(!v1_pending)begin
            v1_tx_addr<=v1_select ? v1_addr:raster_addr;
            v1_tx_data<=v1_select ? v1_data:raster_data;
            v1_tx_mask<=v1_select ? v1_mask:raster_mask;
            v1_tx_write<=v1_select ? v1_write:raster_write;
        end
    end
    assign v1_valid=v1_pending;
    assign ext_done=v1_select ? v1_done:old_done;
    gpu_geometry u_v1(.child_resetn(engine_resetn[9:4]),.clk(mem_clk),.rst(!engine_resetn[2]),.start(ext_start && v1_select),.command(ext_command),
        .observe_packet_words(observe_packet_words),.busy(),.done(v1_done),
        .geom_errors(geometry_stat[0]),.vertices(geometry_stat[1]),.triangles(geometry_stat[2]),
        .culled(geometry_stat[3]),.clipped(geometry_stat[4]),.slivers(geometry_stat[5]),.geom_cycles(geometry_stat[6]),.rejected(v1_rejected),.fragments(v1_fragments),.passed(v1_passed),
        .texture_hits(v1_hits),.texture_misses(v1_misses),.valid(v1_request),.write(v1_write),
        .addr(v1_addr),.wr_data(v1_data),.wr_mask(v1_mask),
        .ready(v1_accepted && v1_select),.rd_valid(v1_rx_valid && v1_select),.rd_data(v1_rx_data));
    // The ordered command queue starts only one engine at a time; each engine
    // drops VALID before completion. Use those registered request flags for
    // transaction control. The wide payload's owner mux must not feed WRITE
    // and then loop through arbiter READY into the engine state machines.
    assign valid=legacy_valid || v1_valid;
    assign write=(legacy_valid && legacy_write) || (v1_valid && v1_tx_write);
    assign addr=ext_active ? v1_tx_addr:legacy_addr;
    assign wr_data=ext_active ? v1_tx_data:legacy_data;
    assign wr_mask=ext_active ? v1_tx_mask:legacy_mask;
    gpu_raster u_raster (.child_resetn(engine_resetn[11:10]),
        .clk(mem_clk),.rst(!engine_resetn[1]),.start(ext_start && raster_selected),.command(ext_command),.busy(),.done(old_done),
        .rejected(raster_rejected),.fragments(raster_fragments),.passed(raster_passed),
        .valid(raster_valid),.write(raster_write),.addr(raster_addr),.wr_data(raster_data),.wr_mask(raster_mask),
        .ready(v1_accepted && raster_selected),.rd_data(v1_rx_data),.rd_valid(v1_rx_valid && raster_selected));
    blitter u_blitter (
        .clk(mem_clk), .rst(!engine_resetn[0]), .cmd_we(command_we), .cmd_data(queue_data), .cmd_full(command_full),
        .err_cmd_lost(command_lost), .err_cmd_bad(command_bad), .cmd_done(done_count), .busy(blitter_busy),
        .ext_start(ext_start),.ext_active(ext_active),.ext_command(ext_command),.ext_done(ext_done),
        .s_req(s_req), .s_addr(s_addr), .s_len(s_len), .s_valid(s_valid), .s_data(s_data), .s_done(s_done),
        .w_req(w_req), .w_addr(w_addr), .w_len(w_len), .w_data(w_data), .w_mask(w_mask), .w_ready(w_ready), .w_done(w_done),
        .f_req(f_req),.f_addr(f_addr),.f_len(f_len),.f_color(f_color),.f_done(f_done),
        .c_req(c_req), .c_addr(c_addr), .c_wdata(c_data), .c_wmask(c_mask), .c_ack(c_ack),
        .font_addr(font_addr), .font_q(font_q), .debug_state(debug_blitter));
    gpu_blit_dma u_dma (
        .clk(mem_clk), .rst(!engine_resetn[3]),
        .s_req(s_req), .s_addr(s_addr), .s_len(s_len), .s_valid(s_valid), .s_data(s_data), .s_done(s_done),
        .w_req(w_req), .w_addr(w_addr), .w_len(w_len), .w_data(w_data), .w_mask(w_mask), .w_ready(w_ready), .w_done(w_done),
        .f_req(f_req),.f_addr(f_addr),.f_len(f_len),.f_color(f_color),.f_done(f_done),
        .c_req(c_req), .c_addr(c_addr), .c_wdata(c_data), .c_wmask(c_mask), .c_ack(c_ack),
        .valid(legacy_valid), .write(legacy_write), .addr(legacy_addr), .wr_data(legacy_data), .wr_mask(legacy_mask),
        .ready(ready), .rd_data(rd_data), .rd_valid(rd_valid && !ext_active));
    assign debug_accept=hresetn && bus_command && !queue_full;
    assign debug_state={ext_command[31:0],queue_data,debug_blitter,
        command_bad,command_lost,
        8'd0,engine_resetn,mrst,command_word,queue_valid,queue_pop,command_we,command_full,blitter_busy,ext_start,ext_active,
        16'd0,done_count};
endmodule
`default_nettype wire
"}

{"content": "// Neo diagnostic only: coherent GPU snapshots independent of cdc_word.
// No output controls the GPU. One outstanding request, held data until ACK.
`default_nettype none
module neo_gpu_debug (
    input wire hclk, resetn, mem_clk,
    input wire hsel, hwrite,
    input wire [1:0] htrans,
    input wire [31:0] haddr, hwdata,
    output reg [31:0] hrdata,
    output wire hready,
    input wire host_accept,
    input wire [255:0] live,
    input wire [63:0] observe_packet_words
);
    reg [1:0] mem_up=0;
    always @(posedge mem_clk or negedge resetn)
        if(!resetn)mem_up<=0;else mem_up<={mem_up[0],1'b1};
    reg request=0, ack=0;
    reg [1:0] req_s=0, ack_s=0, ready_s=0;
    reg [31:0] host_words=0, received=0, last_word=0;
    reg [319:0] held=0, snapshot=0;
    reg busy=0, valid=0;
    // Ungated observation path, independent of the snapshot handshake.
    // These per-bit synchronizers are NOT an atomic multi-bit capture. Read
    // only with the GPU idle, require repeated equal samples, and interpret
    // them as diagnostic evidence only. They never control the GPU or ACK.
    reg [63:0] observe_words_s1=0,observe_words_s2=0;
    reg [31:0] observe_meta_s1=0,observe_meta_s2=0;
    wire [31:0] observe_meta={8'd0,live[255:248],4'd0,valid,busy,
        ready_s,mem_up,ack_s,ack,req_s,request};
    always @(posedge hclk)begin
        if(!resetn)begin
            observe_words_s1<=0;observe_words_s2<=0;
            observe_meta_s1<=0;observe_meta_s2<=0;
        end else begin
            observe_words_s1<=observe_packet_words;observe_words_s2<=observe_words_s1;
            observe_meta_s1<=observe_meta;observe_meta_s2<=observe_meta_s1;
        end
    end
    reg [31:0] sequence_id=0;
    reg bus_write=0;
    reg [7:0] bus_addr=0;
    // One wait state separates address decode from the registered response.
    // Four identical selectors keep each decode local to one response byte.
    // Only this diagnostic slave changes latency; GPU commands are unaffected.
    reg read_wait=0;
    reg [67:0] read_select /* synthesis syn_preserve=1 */ = 0;
    assign hready=!read_wait;
    always @(posedge hclk)
        if(!resetn)read_wait<=0;
        else if(read_wait)read_wait<=0;
        else read_wait<=hsel && htrans[1] && !hwrite;
    genvar sel;
    generate for(sel=0;sel<68;sel=sel+1)begin: decode
        always @(posedge hclk)
            if(!resetn)read_select[sel]<=0;
            else if(hready)read_select[sel]<=(haddr[7:0]==(sel%17)*4);
    end endgenerate
    wire [31:0] register_value [0:16];
    assign register_value[0]=32'h4e474442; // NGDB
    assign register_value[1]={29'd0,ready_s[1],valid,busy};
    assign register_value[2]=host_words;
    assign register_value[3]=sequence_id;
    assign register_value[4]=snapshot[287:256];
    assign register_value[5]=snapshot[319:288];
    assign register_value[6]=observe_words_s2[31:0]; // geometry captured header
    assign register_value[7]=observe_words_s2[63:32]; // pixel captured header
    assign register_value[16]=observe_meta_s2; // raw handshake/opcode, not a snapshot
    genvar lane;
    generate for(lane=0;lane<8;lane=lane+1)begin: snapshot_word
        assign register_value[8+lane]=snapshot[lane*32+:32];
    end endgenerate
    wire [31:0] response_data;
    genvar byte_index;
    generate for(byte_index=0;byte_index<4;byte_index=byte_index+1)begin: response
        integer k;
        reg [7:0] selected_byte;
        assign response_data[byte_index*8+:8]=selected_byte;
        always @* begin
            selected_byte=0;
            for(k=0;k<17;k=k+1)
                selected_byte=selected_byte |
                    ({8{read_select[byte_index*17+k]}} & register_value[k][byte_index*8+:8]);
        end
    end endgenerate
    always @(posedge mem_clk)begin
        if(!mem_up[1])begin
            req_s<=0;ack<=0;held<=0;received<=0;last_word<=0;
        end else begin
            req_s<={req_s[0],request};
            if(live[36])begin // gpu_accel command_we, same mem_clk edge
                received<=received+1'b1;last_word<=live[223:192];
            end
            if(req_s[1]!=ack)begin
                held<={last_word,received,live};
                ack<=req_s[1];
            end
        end
    end
    always @(posedge hclk)begin
        if(!resetn)begin
            request<=0;ack_s<=0;ready_s<=0;host_words<=0;snapshot<=0;
            busy<=0;valid<=0;sequence_id<=0;bus_write<=0;bus_addr<=0;hrdata<=0;
        end else begin
            ack_s<={ack_s[0],ack};
            ready_s<={ready_s[0],mem_up[1]};
            if(hready)begin
                bus_write<=hsel && htrans[1] && hwrite;
                bus_addr<=haddr[7:0];
            end
            if(host_accept)host_words<=host_words+1'b1;
            if(bus_write && hready && bus_addr==8'h04 && hwdata[0] && !busy && ready_s[1])begin
                request<=~request;busy<=1;
            end
            if(busy && ack_s[1]==request)begin
                snapshot<=held;busy<=0;valid<=1;sequence_id<=sequence_id+1'b1;
            end
            hrdata<=response_data;
        end
    end
endmodule
`default_nettype wire
"}

{"content": "// ddr_dcfifo.v — FIFO double horloge (pointeurs Gray) entre le domaine d'acquisition (clk 100 MHz, sortie de
// raw_fifo / event_enc) et le domaine de l'IP DDR3 (clk_out 75 MHz, ddr_writer) — ARCHI_V3 § 9.2.
//
// Écrite à la main plutôt que générée par l'IP FIFO Gowin : une netlist chiffrée ne se simule pas, celle-ci
// passe au banc cocotb (rapports 100/75 et 100/50, vide/plein, 10 000 mots aléatoires, pertes comptées).
// Aucune perte silencieuse : un mot présenté quand la FIFO est pleine est refusé (wr_ready = 0) ET compté
// dans `wr_lost` (domaine écriture) — l'appelant décide quoi en faire (ddr_writer publie le compteur).
// Neo-only isolation experiment: exactly the AHB/DDR command (100-bit) and
// response (64-bit) four-slot specializations use explicit flip-flops. All
// pointers, flags, resets and the registered head latency are unchanged.
// Larger FIFOs and the USB debug command FIFO retain inferred memory.
// The shared Pro Dock source is NOT modified by this variant.
`default_nettype none
module ddr_dcfifo #(
    parameter WIDTH      = 64,
    parameter DEPTH_LOG2 = 9          // 512 mots
) (
    // écriture
    input  wire             wr_clk,
    input  wire             wr_rst,       // synchrone au domaine écriture
    input  wire             wr_valid,
    input  wire [WIDTH-1:0] wr_data,
    output wire             wr_ready,     // = pas pleine
    output wire             wr_full,      // registered fullness, independent of reset
    output reg  [31:0]      wr_lost,      // mots refusés (pleine), jamais remis à zéro sauf reset
    output wire [DEPTH_LOG2:0] wr_count,  // remplissage vu du côté écriture (pessimiste)
    // lecture
    input  wire             rd_clk,
    input  wire             rd_rst,       // synchrone au domaine lecture
    output wire             rd_valid,     // = pas vide ; rd_data valide
    output wire [WIDTH-1:0] rd_data,
    input  wire             rd_ready,     // consomme le mot présenté
    output wire [DEPTH_LOG2:0] rd_count   // remplissage vu du côté lecture (pessimiste)
);
    localparam AW = DEPTH_LOG2;

    wire [WIDTH-1:0] storage_read;

    // --- pointeurs binaires et Gray (AW+1 bits : le bit de poids fort distingue plein de vide) ---
    reg  [AW:0] wr_bin, wr_gray, rd_bin, rd_gray;
    reg  [AW:0] wr_gray_s1, wr_gray_s2;      // wr_gray synchronisé dans rd_clk
    reg  [AW:0] rd_gray_s1, rd_gray_s2;      // rd_gray synchronisé dans wr_clk

    function [AW:0] bin2gray; input [AW:0] b; begin bin2gray = b ^ (b >> 1); end endfunction
    function [AW:0] gray2bin; input [AW:0] g; integer i; reg [AW:0] b;
        begin b = 0; for (i = AW; i >= 0; i = i - 1) b[i] = (i == AW) ? g[i] : b[i+1] ^ g[i]; gray2bin = b; end
    endfunction

    // --- côté écriture ----------------------------------------------------------------------
    // `full` et `wr_count` sont REGISTRÉS (E2-e, 2026-09-20) : calculés à partir du pointeur d'écriture du
    // cycle suivant et du pointeur de lecture synchronisé courant. Sans cela, la chaîne Gray → gray2bin →
